fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    
    for &ch in s.iter() {
        if ch >= 'A' && ch <= 'Z' {
            // Convert uppercase ASCII to lowercase by adding 32
            let lowercase_code = ch as u32 + 32;
            result.push(char::from_u32(lowercase_code).unwrap());
        } else {
            result.push(ch);
        }
    }
    
    result
}